INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO26-006','beginner','Zasilanie','USB-C Power Delivery EPR','','description: Ładowanie EPR wymaga zgodnego źródła, urządzenia i kabla. step: Porównaj napięcie i moc ładowarki z wymaganiami laptopa.','','',''),
('beginner:ZERO26-007','beginner','Pamięć i RAM','4-Rank CUDIMM','','description: Nowe moduły pamięci wymagają obsługi płyty, CPU i firmware. step: Sprawdź QVL i wersję BIOS przed montażem.','','',''),
('beginner:ZERO26-008','beginner','Pamięć i RAM','CAMM2 i LPCAMM2','','description: Nowe formaty pamięci laptopowej nie są zwykłym SO-DIMM. step: Odszukaj instrukcję serwisową i numer części OEM.','','',''),
('beginner:ZERO26-009','beginner','Nowe platformy i AI','NPU — jednostka przetwarzania neuronowego','','description: NPU przyspiesza wybrane zadania AI i wymaga odpowiedniego sterownika. step: Sprawdź, czy Menedżer zadań pokazuje NPU.','','',''),
('beginner:ZERO26-010','beginner','Nowe platformy i AI','Copilot+ PC i 40 TOPS','','description: Wiele funkcji Copilot+ wymaga NPU o odpowiedniej wydajności i zgodnego systemu. step: Zweryfikuj wymaganie konkretnej funkcji na dokumentacji Microsoft.','','',''),
('beginner:ZERO26-011','beginner','Grafika i GPU','Blackwell — architektura RTX 50','','description: RTX 50 wykorzystuje architekturę Blackwell i nową generację rdzeni. step: Zapisz model GPU, sterownik i VBIOS.','','',''),
('beginner:ZERO26-012','beginner','Grafika i GPU','DLSS Multi Frame Generation','','description: Generowanie klatek AI nie zastępuje pomiaru opóźnień i stabilności renderowania. step: Porównaj test bazowy bez Frame Generation z trybem włączonym.','','',''),
('beginner:ZERO26-013','beginner','Grafika i GPU','GPU hotspot i pamięć VRAM','','description: Temperatura rdzenia nie opisuje wszystkich punktów cieplnych GPU. step: Monitoruj temperaturę rdzenia, hotspot i VRAM podczas krótkiego testu.','','',''),
('beginner:ZERO26-014','beginner','Dyski i dane','NVMe Critical Warning','','description: Krytyczny status SMART wymaga szybkiej oceny ryzyka danych. step: Zapisz log NVMe i wykonaj kopię, jeżeli nośnik jest stabilny.','','',''),
('beginner:ZERO26-015','beginner','Dyski i dane','NVMe Percentage Used','','description: Wskaźnik użycia nośnika nie jest prostym licznikiem czasu do awarii. step: Porównaj odczyt z dokumentacją producenta SSD.','','',''),
('beginner:ZERO26-016','beginner','Dyski i dane','NVMe Media and Data Integrity Errors','','description: Błędy integralności wymagają ochrony danych i analizy trendu. step: Nie wykonuj wielokrotnych benchmarków; najpierw zabezpiecz dane.','','',''),
('beginner:ZERO26-017','beginner','Dyski i dane','PCIe 5.0 SSD i thermal throttling','','description: Wysoka temperatura może ograniczyć transfer SSD. step: Sprawdź radiator i temperaturę kontrolera bez testu zapisu na uszkodzonym dysku.','','',''),
('beginner:ZERO26-018','beginner','Dyski i dane','Secure Erase vs formatowanie','','description: Formatowanie partycji i komendy sanitization mają różne skutki. step: Potwierdź zgodę klienta i kopię zanim zaczniesz kasowanie.','','',''),
('beginner:ZERO26-019','beginner','Windows i bezpieczeństwo','Secure Boot 2023 certificates','','description: Microsoft aktualizuje certyfikaty z 2011 do nowych certyfikatów 2023. step: Sprawdź status certyfikatów i BIOS OEM bez wyłączania Secure Boot.','','',''),
('beginner:ZERO26-020','beginner','Windows i system','Windows 11 26H2 — znane problemy','','description: Release Health podaje aktualny stan błędów oraz ich rozwiązania. step: Sprawdź dokładną kompilację i numer KB przed naprawą.','','',''),
('beginner:ZERO26-021','beginner','Windows i system','KB5127936 — poprawka Preview','','description: Opcjonalna aktualizacja Preview może zawierać poprawki i znane problemy. step: Nie instaluj jej bez sprawdzenia, czy dotyczy badanego objawu.','','',''),
('beginner:ZERO26-022','beginner','Audio i urządzenia','USB Audio Class 1.0 — Code 10','','description: Część starszych urządzeń USB audio może mieć problem po aktualizacji systemu. step: Sprawdź wersję Windows, identyfikator urządzenia i release health.','','',''),
('beginner:ZERO26-023','beginner','Audio i urządzenia','HDMI/DisplayPort Audio na Radeon','','description: Problem z audio może zależeć od wyjścia GPU, sterownika i aktualizacji Windows. step: Wybierz właściwe urządzenie wyjściowe i przetestuj kabel oraz port.','','',''),
('beginner:ZERO26-024','beginner','Audio i urządzenia','Bluetooth LE Audio','','description: LE Audio zależy od zgodności adaptera, słuchawek i sterowników. step: Sprawdź obsługiwany profil, ponowne parowanie i wybudzenie.','','',''),
('beginner:ZERO26-025','beginner','Audio i urządzenia','Multi-App Camera w Windows 11 26H2','','description: Kilka aplikacji może współdzielić strumień kamery na zgodnych urządzeniach. step: Przetestuj kamerę w jednej i dwóch aplikacjach.','','',''),
('beginner:ZERO26-026','beginner','Audio i urządzenia','Windows Basic Camera mode','','description: Uproszczony tryb kamery może pomagać w diagnostyce stabilności. step: Sprawdź ustawienia systemowe i zasady urządzenia.','','',''),
('beginner:ZERO26-027','beginner','Windows i system','Safeguard hold aktualizacji Windows','','description: Windows może wstrzymać aktualizację z powodu problemu zgodności. step: Nie wymuszaj aktualizacji przed usunięciem przyczyny.','','',''),
('beginner:ZERO26-028','beginner','Diagnostyka i pomiary','WHEA-Logger PCIe','','description: WHEA opisuje raport błędu sprzętowego, a nie wskazuje automatycznie winnego elementu. step: Zapisz pełne zdarzenie i skoreluj je z testem.','','',''),
('beginner:ZERO26-029','beginner','BIOS i firmware','UEFI capsule firmware','','description: Firmware może być aktualizowany przez mechanizm kapsułkowy UEFI. step: Sprawdź model, podpis, źródło pliku i procedurę OEM.','','',''),
('beginner:ZERO26-030','beginner','Zasilanie','Zasilanie GPU 12V-2x6','','description: Złącza zasilania GPU wysokiej mocy wymagają właściwego przewodu i pełnego osadzenia. step: Odłącz zasilanie i obejrzyj wtyk pod kątem przebarwień.','','',''),
('beginner:ZERO26-031','beginner','Procesory i platformy','Ryzen 9000 — sterowniki chipsetu','','description: Właściwy pakiet zależy od systemu i modelu platformy. step: Sprawdź numer chipsetu, BIOS i pakiet OEM/AMD.','','',''),
('beginner:ZERO26-032','beginner','Procesory i platformy','Intel Core Ultra 200S Plus','','description: Nowe procesory mogą wymagać aktualizacji BIOS i określonych modułów pamięci. step: Sprawdź listę CPU i QVL płyty.','','',''),
('beginner:ZERO26-033','beginner','Obraz i monitory','Oled retention vs burn-in','','description: Chwilowa retencja i trwałe wypalenie nie są tym samym zjawiskiem. step: Testuj jednolite plansze przy ustawieniach zalecanych przez producenta.','','',''),
('beginner:ZERO26-034','beginner','Obraz i monitory','Mini-LED blooming','','description: Poświata wokół jasnych obiektów może wynikać z lokalnego wygaszania stref. step: Porównaj obraz z wyłączonym i włączonym local dimming.','','',''),
('beginner:ZERO26-035','beginner','Grafika i GPU','Advanced Optimus','','description: Tryb hybrydowy zmienia sposób przekazywania obrazu przez iGPU i dGPU. step: Zapisz tryb GPU i przetestuj ekran wewnętrzny oraz zewnętrzny.','','',''),
('beginner:ZERO26-036','beginner','Sieć i łączność','M.2 Key E Wi-Fi','','description: Slot M.2 Key E nie gwarantuje zgodności każdego modułu Wi-Fi. step: Sprawdź interfejs, whitelist i liczbę przewodów antenowych.','','',''),
('beginner:ZERO26-037','beginner','Sieć i łączność','Intel driver 24.70 Wi-Fi/Bluetooth','','description: Wersje sterowników są zależne od adaptera i systemu. step: Pobierz pakiet z Intel/OEM i potwierdź ID sprzętu.','','',''),
('beginner:ZERO26-038','beginner','Sieć i łączność','WPA3 i sieć gościnna','','description: Nowe standardy zabezpieczeń muszą być wspierane po obu stronach połączenia. step: Sprawdź tryb bezpieczeństwa i zgodność urządzenia klienckiego.','','',''),
('beginner:ZERO26-039','beginner','Sieć i łączność','2.5/5/10 GbE link negotiation','','description: Szybkość Ethernet zależy od obu portów i kabla. step: Odczytaj negocjowany link i sprawdź inny certyfikowany przewód.','','',''),
('beginner:ZERO26-040','beginner','Dyski i dane','Kopia przed naprawą NVMe','','description: Przy podejrzeniu awarii SSD priorytetem jest kopia, nie benchmark. step: Sprawdź stabilność nośnika i wybierz bezpieczną metodę obrazu.','','','');
